print('note unique samples',len(set(r['notes'] for r in rows)))
print('dup ids')
d=collections.defaultdict(list)
for i,r in enumerate(rows): d[r['record_id']].append((i,r))
for k,v in d.items():
 if len(v)>1: print(k,[(i,r['event_time'],r['amount_str'],r['notes']) for i,r in v])
